await (async (page) => {
 const results=[];const check=(v,name)=>{if(!v)throw new Error(name);results.push({name,status:'PASS'});};
 await page.reload();const r=page.getByRole('region',{name:'Book workspace local preview'});await r.getByRole('heading',{name:'Lantern Garden',exact:true}).waitFor();const name=r.getByRole('textbox',{name:'Selected chapter title',exact:true});
 await name.fill('A-only retained rename');await r.getByRole('button',{name:'Open chapter 2: The bridge',exact:true}).click();check(await name.inputValue()==='The bridge','rename draft is chapter scoped');await r.getByRole('button',{name:'Open chapter 1: Arrival',exact:true}).click();check(await name.inputValue()==='A-only retained rename','unsubmitted rename survives same-owner chapter navigation');
 await page.getByRole('button',{name:'Use Author B',exact:true}).click();await page.getByRole('button',{name:'Open B book',exact:true}).click();await r.getByRole('heading',{name:"B's invented private book",exact:true}).waitFor();check(await name.inputValue()==='B-only chapter'&&!(await r.innerText()).includes('A-only retained rename'),'rename draft is not rendered under B');await page.getByRole('button',{name:'Use Author A',exact:true}).click();await r.getByRole('heading',{name:'Lantern Garden',exact:true}).waitFor();check(await name.inputValue()==='A-only retained rename','rename draft returns only to verified A');
 const notes=r.getByRole('textbox',{name:'Planning notes for this book',exact:true});await notes.fill('First notes');await page.getByRole('button',{name:'Pause next change',exact:true}).click();await r.getByRole('button',{name:'Apply book notes locally',exact:true}).click();await r.getByRole('status').filter({hasText:'Applying a change'}).waitFor();await notes.fill('Later typing retains focus');await notes.evaluate(el=>el.setSelectionRange(5,5));
 await page.getByRole('button',{name:'Release paused change',exact:true}).evaluate(el=>el.click());await r.getByRole('status').filter({hasText:'confirmed in this local test session only'}).waitFor();
 const focus=await notes.evaluate(el=>({focused:document.activeElement===el,start:el.selectionStart,end:el.selectionEnd}));check(focus.focused&&focus.start===5&&focus.end===5&&await notes.inputValue()==='Later typing retains focus','acknowledgement preserves actual writer focus, caret and newer notes');
 return {source:'1ff1098cd73066c8bfd1084b72d076b4284896e1',browser:page.context().browser()?.version(),results};
})(page);
